// rate_limiter.go
package rate_limiter

import (
	"fmt"
	"sync"
	"time"
)

// Clock is an interface for time sources.
type Clock interface {
	Now() time.Time
}

// Limiter is a token bucket rate limiter.
type Limiter struct {
	mu         sync.Mutex
	rate       float64 // tokens per second
	burst      float64 // max tokens
	tokens     float64 // current tokens
	lastRefill time.Time
	clock      Clock
}

// NewLimiter creates a new Limiter with given rate (tokens/sec) and burst.
// It validates that rate > 0, burst > 0, and clock is not nil.
func NewLimiter(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, fmt.Errorf("rate must be positive")
	}
	if burst <= 0 {
		return nil, fmt.Errorf("burst must be positive")
	}
	if clock == nil {
		return nil, fmt.Errorf("clock must not be nil")
	}
	return &Limiter{
		rate:       rate,
		burst:      float64(burst),
		tokens:     float64(burst), // start full
		lastRefill: clock.Now(),
		clock:      clock,
	}, nil
}

// AllowN reports whether n tokens are available and consumes them if so.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true // no tokens needed
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// refill adds tokens based on elapsed time since last refill.
func (l *Limiter) refill() {
	now := l.clock.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.lastRefill = now
	}
}
