package ratelimit

import (
	"sync"
	"time"
)

// Clock provides the current time.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	rate     float64 // tokens per second
	burst    float64 // maximum token capacity
	tokens   float64 // current token count
	last     time.Time
	clock    Clock
}

// NewLimiter creates a Limiter with the given rate (tokens/sec) and burst capacity.
// It panics if rate <= 0 or burst <= 0.
func NewLimiter(rate, burst float64, clk Clock) *Limiter {
	if rate <= 0 {
		panic("rate must be positive")
	}
	if burst <= 0 {
		panic("burst must be positive")
	}
	if clk == nil {
		clk = realClock{}
	}
	return &Limiter{
		rate:  rate,
		burst: burst,
		tokens: burst, // start full
		last:  clk.Now(),
		clock: clk,
	}
}

// AllowN reports whether n tokens are available at the current time.
// If so, it consumes n tokens and returns true; otherwise it returns false.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	l.last = now

	// Add tokens based on elapsed time, capped at burst.
	l.tokens += elapsed * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}
