		burst:  burst,
		tokens: burst, // start full
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens are available and consumes them if so.
// It returns true if the request is allowed, false otherwise.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	l.tokens += elapsed * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.last = now

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}
