				lim.AllowN(1)
			}
			done <- true
		}()
	}
	for i := 0; i < 10; i++ {
		<-done
	}
	// After 1000 requests, tokens should be 0 (since burst=100, but rate high)
	lim.mu.Lock()
	tokens := lim.tokens
	lim.mu.Unlock()
	if tokens != 0 {
